class Solution {
public:
    int chalkReplacer(vector<int>& chalk, int k) {
        long long total = 0;
        for (int c : chalk) total += c;
        long long rem = k % total;
        for (int i = 0; i < (int)chalk.size(); i++) {
            if (rem < chalk[i]) return i;
            rem -= chalk[i];
        }
        return -1;
    }
};
